/**  A cloudflared `config.yml` (ingress rules). */
"configYaml" | 
/**  A Docker Compose service running the tunnel. */
"dockerCompose" | 
/**  Terraform for the Cloudflare provider v5, with `import` blocks. */
"terraform";

